/**
 * API Client — Dual Mode
 * =======================
 * In development (npm run dev): fetches from the live FastAPI backend.
 * In production  (npm run build → GitHub Pages): fetches from static JSON
 * files located in /data/ that were generated by export_static_api.py.
 *
 * Write operations (createBet, settleBet) are disabled in static mode.
 */

const BASE_URL = import.meta.env.VITE_API_URL || "http://localhost:8000";
const IS_STATIC = import.meta.env.PROD;

// ─── Live API helpers (development) ──────────────────────────────────

async function get(path) {
  const res = await fetch(`${BASE_URL}${path}`);
  if (!res.ok) throw new Error(`API error: ${res.status}`);
  return res.json();
}

async function post(path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  if (!res.ok) throw new Error(`API error: ${res.status}`);
  return res.json();
}

async function patch(path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  if (!res.ok) throw new Error(`API error: ${res.status}`);
  return res.json();
}

// ─── Static JSON helper (production / GitHub Pages) ──────────────────

async function staticJson(filename) {
  const res = await fetch(`${import.meta.env.BASE_URL}data/${filename}`);
  if (!res.ok) throw new Error(`Static data not found: ${filename}`);
  return res.json();
}

// ─── Exported API object ─────────────────────────────────────────────

export const api = {
  // Fighters
  getFighters: (skip = 0, limit = 50, active_only = false) => {
    if (IS_STATIC) {
      return staticJson("fighters.json").then((fighters) => {
        let filtered = fighters;
        if (active_only) filtered = filtered.filter((f) => f.is_active);
        return filtered.slice(skip, skip + limit);
      });
    }
    return get(`/fighters?skip=${skip}&limit=${limit}&active_only=${active_only}`);
  },

  getFighter: (id) => {
    if (IS_STATIC) return staticJson(`fighters/${id}.json`);
    return get(`/fighters/${id}`);
  },

  getFighterFights: (id) => {
    if (IS_STATIC) return staticJson(`fighters/${id}_fights.json`);
    return get(`/fighters/${id}/fights`);
  },

  // Predictions
  getPredictions: (modelVersion = null) => {
    if (IS_STATIC) {
      return staticJson("predictions.json").then((rows) =>
        modelVersion ? rows.filter((r) => r.model_version === modelVersion) : rows
      );
    }
    const params = modelVersion ? `?model_version=${modelVersion}` : '';
    return get(`/predictions${params}`);
  },

  getResults: (modelVersion = null) => {
    if (IS_STATIC) {
      return staticJson("results.json").then((rows) =>
        modelVersion ? rows.filter((r) => r.model_version === modelVersion) : rows
      );
    }
    const params = modelVersion ? `?model_version=${modelVersion}` : '';
    return get(`/predictions/results${params}`);
  },

  getModels: () => {
    if (IS_STATIC) return staticJson("models.json");
    return get("/predictions/models");
  },

  // Bets (read-only in static mode)
  getBets: () => {
    if (IS_STATIC) return staticJson("bets.json");
    return get("/bets");
  },
  createBet: (data) => {
    if (IS_STATIC) throw new Error("Write operations are disabled on the static site.");
    return post("/bets", data);
  },
  settleBet: (id, data) => {
    if (IS_STATIC) throw new Error("Write operations are disabled on the static site.");
    return patch(`/bets/${id}/settle`, data);
  },

  // Blog
  getBlogPosts: () => {
    if (IS_STATIC) return staticJson("blog.json");
    return get("/blog");
  },
  getBlogPost: (slug) => {
    if (IS_STATIC) return staticJson(`blog/${slug}.json`);
    return get(`/blog/${slug}`);
  },

  // Health — always returns ok in static mode
  healthCheck: () => {
    if (IS_STATIC) return Promise.resolve({ status: "static" });
    return get("/health");
  },
};
